class Solution:
    def colorBorder(self, grid: List[List[int]], row: int, col: int, color: int) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        orig = grid[row][col]
        seen = [[False] * n for _ in range(m)]

        def dfs(r, c):
            seen[r][c] = True
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == orig and not seen[nr][nc]:
                    dfs(nr, nc)

        dfs(row, col)
        for r in range(m):
            for c in range(n):
                if seen[r][c]:
                    if r == 0 or c == 0 or r == m - 1 or c == n - 1:
                        grid[r][c] = color
                    else:
                        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                            if grid[r+dr][c+dc] != orig:
                                grid[r][c] = color
                                break
        return grid

