class Solution {
public:
    vector<vector<int>> colorBorder(vector<vector<int>>& grid, int row, int col, int color) {
        int m = grid.size(), n = grid[0].size(), orig = grid[row][col];
        vector<vector<bool>> seen(m, vector<bool>(n, false));
        function<void(int,int)> dfs = [&](int r, int c) {
            seen[r][c] = true;
            int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == orig && !seen[nr][nc])
                    dfs(nr, nc);
            }
        };
        dfs(row, col);
        int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (seen[r][c]) {
                    bool border = r == 0 || c == 0 || r == m - 1 || c == n - 1;
                    for (auto& d : dirs)
                        if (!border) {
                            int nr = r + d[0], nc = c + d[1];
                            if (grid[nr][nc] != orig) border = true;
                        }
                    if (border) grid[r][c] = color;
                }
        return grid;
    }
};

