class Solution {
    private int m, n, orig;
    private boolean[][] seen;
    private int[][] grid;
    private final int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};

    public int[][] colorBorder(int[][] grid, int row, int col, int color) {
        this.grid = grid;
        m = grid.length; n = grid[0].length; orig = grid[row][col];
        seen = new boolean[m][n];
        dfs(row, col);
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (seen[r][c]) {
                    boolean border = r == 0 || c == 0 || r == m - 1 || c == n - 1;
                    for (int[] d : dirs)
                        if (!border && grid[r + d[0]][c + d[1]] != orig) border = true;
                    if (border) grid[r][c] = color;
                }
        return grid;
    }

    private void dfs(int r, int c) {
        seen[r][c] = true;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == orig && !seen[nr][nc])
                dfs(nr, nc);
        }
    }
}

