var colorBorder = function(grid, row, col, color) {
    const m = grid.length, n = grid[0].length, orig = grid[row][col];
    const seen = Array.from({length: m}, () => new Array(n).fill(false));
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    const stack = [[row, col]];
    seen[row][col] = true;
    while (stack.length) {
        const [r, c] = stack.pop();
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === orig && !seen[nr][nc]) {
                seen[nr][nc] = true;
                stack.push([nr, nc]);
            }
        }
    }
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (seen[r][c]) {
                let border = r === 0 || c === 0 || r === m - 1 || c === n - 1;
                for (const [dr, dc] of dirs)
                    if (!border && grid[r + dr][c + dc] !== orig) border = true;
                if (border) grid[r][c] = color;
            }
    return grid;
};

