class Solution:
    def colorBorder(self, grid: List[List[int]], row: int, col: int, color: int) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        orig = grid[row][col]
        s = -orig
        border = set()

        def dfs(r, c):
            grid[r][c] = s
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < m and 0 <= nc < n):
                    border.add((r, c))
                elif grid[nr][nc] == orig:
                    dfs(nr, nc)
                elif grid[nr][nc] != s:
                    border.add((r, c))

        dfs(row, col)
        for r in range(m):
            for c in range(n):
                if grid[r][c] == s:
                    grid[r][c] = color if (r, c) in border else orig
        return grid

