        int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        function<void(int,int)> dfs = [&](int r, int c) {
            grid[r][c] = s;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) { isBorder[r][c] = true; continue; }
                if (grid[nr][nc] == orig) dfs(nr, nc);
                else if (grid[nr][nc] != s) isBorder[r][c] = true;
            }
        };
        dfs(row, col);
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (grid[r][c] == s)
                    grid[r][c] = isBorder[r][c] ? color : orig;
        return grid;
    }
};

