class Solution {
    private int m, n, orig;
    private int[][] grid;
    private boolean[][] isBorder;
    private final int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};

    public int[][] colorBorder(int[][] grid, int row, int col, int color) {
        this.grid = grid;
        m = grid.length; n = grid[0].length;
        orig = grid[row][col];
        isBorder = new boolean[m][n];
        dfs(row, col);
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (grid[r][c] == -orig)
                    grid[r][c] = isBorder[r][c] ? color : orig;
        return grid;
    }

    private void dfs(int r, int c) {
        grid[r][c] = -orig;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) { isBorder[r][c] = true; continue; }
            if (grid[nr][nc] == orig) dfs(nr, nc);
            else if (grid[nr][nc] != -orig) isBorder[r][c] = true;
        }
    }
}

