var colorBorder = function(grid, row, col, color) {
    const m = grid.length, n = grid[0].length;
    const orig = grid[row][col], s = -orig;
    const isBorder = Array.from({length: m}, () => new Array(n).fill(false));
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    const stack = [[row, col]];
    grid[row][col] = s;
    while (stack.length) {
        const [r, c] = stack.pop();
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) { isBorder[r][c] = true; continue; }
            if (grid[nr][nc] === orig) { grid[nr][nc] = s; stack.push([nr, nc]); }
            else if (grid[nr][nc] !== s) isBorder[r][c] = true;
        }
    }
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (grid[r][c] === s)
                grid[r][c] = isBorder[r][c] ? color : orig;
    return grid;
};
